"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[52285],{77776:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"SettingsGuiController","desc":"Binds the Studio-authored `StarterGui.SettingsGui` to `SettingsClient`.\\nOpens from a TopbarPlus icon (toggle key P). Each row maps to one setting\\nkey; a number setting drives a slider, a boolean setting drives a toggle.\\nRows read `SettingsClient.Get`, write `SettingsClient.Set`, and repaint on\\n`Signals.OnSettingChanged` (the join-sync can land after this binds).","realm":["Client"],"source":{"line":12,"path":"src/StarterPlayer/StarterPlayerScripts/SettingsGuiController.client.luau"}}')}}]);